// Üretilen dosya: tool/ozgun/uret.py. Matematik · Analitik geometri: doğru, çember, uzaklık (zor).
const ozMathematics11Zor = <(String, String, List<String>, String)>[
  ('Analitik düzlemde eksenlere uzaklıkları toplamı 4 birim olan noktalar hangi biçimi oluşturur?', 'Köşeleri eksenlerde olan bir kare', ['Merkezi orijinde bir çember', 'Eksenlere paralel bir dikdörtgen', 'Orijinden geçen iki doğru'], '|x| + |y| = 4 eşitliği köşeleri (±4, 0) ve (0, ±4) olan, köşegenleri eksenler üzerinde bulunan bir karedir.'),
  ('Orijine uzaklığı 5 birim olan ve iki koordinatı da tam sayı olan kaç nokta vardır?', '12', ['4', '8', '16'], 'x² + y² = 25 eşitliğini sağlayan tam sayı ikilileri (±5, 0), (0, ±5), (±3, ±4) ve (±4, ±3)\'tür: 4 + 8 = 12 nokta.'),
  ('A(1, 1), B(4, 5) ve C(8, 2) noktalarıyla oluşan ABC üçgeni için hangisi doğrudur?', 'B\'de dik açılı ikizkenar üçgen', ['Eşkenar üçgendir', 'Geniş açılı çeşitkenar üçgendir', 'C köşesinde dik açı olan üçgendir'], '|AB| = 5, |BC| = √(16 + 9) = 5, |AC| = √(49 + 1) = √50\'dir. 25 + 25 = 50 olduğundan B\'de dik açı vardır ve iki dik kenar eşittir.'),
  ('Köşeleri A(0, 0), B(3, 1), C(4, 4) ve D(1, 3) olan dörtgenin bütün kenarları √10\'dur. Bu dörtgen hangisidir?', 'Kare olmayan eşkenar dörtgen', ['Kare', 'Dik açılı olmayan ikizkenar yamuk', 'İkizkenar yamuk'], 'Dört kenar eşit, ancak köşegenler eşit değildir (AC = √32, BD = √8). Köşegenleri eşit olmayan, kenarları eşit dörtgen kare olmayan eşkenar dörtgendir.'),
  ('A(0, 0), B(6, 0) ve C(2, 4) noktalarının üçüne birden eşit uzaklıkta olan nokta hangisidir?', '(3, 1)', ['(2, 2)', '(3, 2)', '(8/3, 4/3)'], 'A ile B\'ye eşit uzaklıktaki noktalar x = 3 doğrusundadır. (3, y) için 9 + y² = 1 + (y − 4)² yazılırsa 8y = 8, y = 1 bulunur.'),
  ('Bir ABC üçgeninde kenarların orta noktaları D(2, 1), E(5, 3) ve F(3, 6)\'dır. Bu üçgenin köşe koordinatlarının toplamı (bütün x ve y değerlerinin toplamı) kaçtır?', '20', ['10', '15', '40'], 'Kenar orta noktalarının koordinat toplamı, köşelerin koordinat toplamına eşittir; çünkü her köşe iki orta noktaya yarı ağırlıkla katılır. D + E + F toplamı 2 + 1 + 5 + 3 + 3 + 6 = 20\'dir.'),
  ('A(1, 2) ve B(4, 8) noktalarından geçen doğru üzerinde, A, B ve C bu sırada dizilmiş olmak üzere |AC| = 3|AB| koşulunu sağlayan C noktası hangisidir?', '(10, 20)', ['(−5, −10)', '(13, 26)', '(10, 18)'], 'C = A + 3(B − A) = (1 + 9, 2 + 18) = (10, 20)\'dir.'),
  ('x ekseni, A(2, −3) ve B(6, 9) noktalarını birleştiren doğru parçasını hangi oranda böler (A tarafından başlayarak)?', '1 : 3', ['1 : 2', '3 : 1', '2 : 3'], 'x ekseni ordinatın 0 olduğu yerdedir. Ordinat −3\'ten 9\'a 12 birim değişir; 0\'a ulaşmak için 3 birim gerekir. Oran 3 : 9 = 1 : 3\'tür.'),
  ('A(2, 5) köşesinden çizilen kenarortayın karşı kenarı kestiği nokta D(8, −1) ise üçgenin ağırlık merkezi hangisidir?', '(6, 1)', ['(5, 2)', '(4, 3)', '(7, 0)'], 'Ağırlık merkezi kenarortayı köşeden itibaren 2 : 1 oranında böler: G = A + (2/3)(D − A) = (2 + 4, 5 − 4) = (6, 1).'),
  ('A(1, 1), B(5, 2) ve C(3, 6) noktaları bir paralelkenarın üç köşesidir. Dördüncü köşe için kaç farklı nokta bulunabilir?', '3', ['1', '2', '4'], 'Verilen üç noktanın her biri dördüncü köşenin karşısındaki köşe olabilir. Bu da A + B − C, A + C − B ve B + C − A olmak üzere üç farklı nokta verir.'),
  ('Köşe koordinatları tam sayı olan bir üçgenin alanı için hangisi her zaman doğrudur?', 'Alanın iki katı bir tam sayıdır', ['Alan her zaman bir tam sayıdır', 'Alan her zaman irrasyonel bir sayıdır', 'Alan 1\'den büyüktür'], 'Ayakkabı bağı formülünde mutlak değer içindeki ifade tam sayıdır. Bu yüzden alanın iki katı tam sayıdır; alan tam ya da buçuklu çıkar.'),
  ('A(−1, m), B(1, 2) ve C(3, 2m) noktaları doğrusal ise m kaçtır?', '4/3', ['2', '1', '−2/3'], 'AB ve BC eğimleri eşitlenir: (2 − m)/2 = (2m − 2)/2, 2 − m = 2m − 2, m = 4/3.'),
  ('Eğimleri m ve −m (m ≠ 0) olan iki doğru, aynı noktadan geçiyorsa birbirine göre nasıl konumlanır?', 'Bu noktadan geçen düşey doğruya göre simetriktir', ['Her durumda birbirine diktir', 'Birbirine paraleldir', 'Bu noktadan geçen yatay doğru üzerinde çakışık olarak bulunur'], 'Eğim açıları α ve 180° − α\'dır. Bu açılar düşey doğruya göre simetrik doğrultular verir; doğrular birbirinin aynadaki görüntüsüdür.'),
  ('(2, 3) noktasından geçen bir doğrunun x eksenini kestiği değer, y eksenini kestiği değerin iki katıdır ve kesim değerleri pozitiftir. Bu doğrunun denklemi hangisidir?', 'x + 2y = 8', ['2x + y = 7', 'x + 2y = 7', 'x + 2y − 4 = 0'], 'Kesimler 2b ve b ise x/(2b) + y/b = 1 olur. (2, 3) için 1/b + 3/b = 1, b = 4; denklem x + 2y = 8\'dir.'),
  ('(m − 1)x + 2y = 3 ve 3x + (m + 4)y = 1 doğrularının paralel olmasını sağlayan m değerlerinin toplamı kaçtır?', '−3', ['3', '−10', '7'], 'Paralellik için (m − 1)/3 = 2/(m + 4) olmalıdır: m² + 3m − 10 = 0, m = 2 ya da m = −5. İki değerde de sabit terimler orantılı değildir; toplam −3\'tür.'),
  ('y = x + 1 doğrusu ile y = mx doğrusunun kesişim noktasının birinci bölgede olması için m hangi koşulu sağlamalıdır?', 'm > 1', ['0 < m < 1', 'm < 0', 'm > 0'], 'x + 1 = mx\'ten x = 1/(m − 1) bulunur. x > 0 için m > 1 olmalıdır; o zaman y = x + 1 de pozitiftir.'),
  ('mx − y = 2 ve x + y = 4 doğrularının kesişim noktasının birinci bölgede olması için m hangi aralıkta olmalıdır?', 'm > 1/2', ['m > 2', '−1 < m < 1/2', 'm < −1'], 'Denklemler toplanırsa x = 6/(m + 1), y = (4m − 2)/(m + 1) bulunur. İkisinin de pozitif olması için m > 1/2 gerekir.'),
  ('m gerçek sayı olmak üzere (m + 1)x + (m − 2)y = 3m − 3 doğruları ailesi m\'nin her değeri için hangi sabit noktadan geçer?', '(1, 2)', ['(2, 1)', '(−1, 2)', '(1, −2)'], 'm(x + y − 3) + (x − 2y + 3) = 0 yazılır. x + y = 3 ve x − 2y = −3 çözülünce (1, 2) bulunur.'),
  ('(2m + 1)x + (1 − m)y = 4m + 5 doğruları ailesinin her üyesinden geçen sabit noktanın koordinatları toplamı kaçtır?', '5', ['3', '4', '6'], 'm(2x − y − 4) + (x + y − 5) = 0 olur. 2x − y = 4 ve x + y = 5 ise nokta (3, 2) ve toplam 5\'tir.'),
  ('kx − y + 1 = 0 ve y = x doğruları arasındaki dar açı 45° ise k kaçtır?', '0', ['−1', '2', '1/2'], 'tan 45° = |(k − 1)/(1 + k)| = 1. k − 1 = −(1 + k) olursa k = 0\'dır; k − 1 = 1 + k çelişkidir.'),
  ('P(1, 1) noktasının önce A(2, 0), sonra B(5, 3) noktasına göre simetriği alınıyor. Son nokta hangisidir?', '(7, 7)', ['(3, −1)', '(9, 5)', '(6, 6)'], 'İlk simetrik (3, −1) olur. Bunun B\'ye göre simetriği (10 − 3, 6 + 1) = (7, 7)\'dir; bu işlem P\'yi 2(B − A) = (6, 6) kadar öteler.'),
  ('P(1, 5) noktasının y = 2x doğrusu üzerindeki dik iz düşümü hangisidir?', '(11/5, 22/5)', ['(2, 4)', '(1, 2)', '(3, 6)'], 'Doğrunun doğrultusu (1, 2) için izdüşüm katsayısı (1 + 10)/5 = 11/5\'tir. İz düşüm (11/5, 22/5) olur.'),
  ('Bir ışık huzmesi A(2, −1) noktasındaki aynadan, ayna x − y + 1 = 0 doğrusu üzerinde olacak biçimde yansıtılıyor. A noktasının görüntüsü hangi noktadır?', '(−2, 3)', ['(0, 1)', '(−3, 2)', '(1, 2)'], 'İfade değeri 2 + 1 + 1 = 4\'tür. Simetrik nokta (2, −1) − 4·(1, −1) = (−2, 3) olur; orta nokta (0, 1) doğrunun üzerindedir.'),
  ('Orijinden 2x + y − 5 = 0 doğrusuna indirilen dikme, doğruyu geçip aynı uzunlukta uzatılırsa ulaşılan nokta nedir?', '(4, 2)', ['(2, 1)', '(5, 0)', '(2, 4)'], 'Orijinde ifade değeri −5\'tir. Simetrik nokta (0, 0) + 2·5/5·(2, 1) = (4, 2) olur; orta nokta (2, 1) doğru üzerindedir.'),
  ('A(1, 3) noktasından çıkan ışık ışını x eksenine çarpıp B(5, 1) noktasına ulaşıyor. Işığın aldığı yolun uzunluğu kaç birimdir?', '4√2', ['6', '2√10', '4√3'], 'B\'nin x eksenine göre simetriği B\'(5, −1) alınır. Yol |AB\'| = √(16 + 16) = 4√2\'dir; yansıma noktası (4, 0).'),
  ('x ≥ 0, y ≥ 0, x + y ≤ 4 ve 2x + y ≤ 6 koşullarını sağlayan (x, y) için 3x + 2y ifadesinin en büyük değeri kaçtır?', '10', ['9', '8', '12'], 'Köşeler (0, 0), (3, 0), (2, 2), (0, 4) noktalarıdır. İfade 0, 9, 10, 8 değerlerini alır; en büyüğü 10\'dur.'),
  ('x ≥ 0, y ≥ 0, 2x + y ≥ 4 ve x + 2y ≥ 4 koşullarını sağlayan (x, y) için x + y toplamının en küçük değeri kaçtır?', '8/3', ['4', '3', '2'], 'Bölgenin köşeleri (0, 4), (4/3, 4/3) ve (4, 0) noktalarıdır. Toplam 4, 8/3 ve 4 olur; en küçüğü 8/3\'tür.'),
  ('O(0, 0) ile B(6, 8) noktalarını birleştiren doğru parçasının orta dikmesi x eksenini hangi apsiste keser?', '25/3', ['25/4', '3', '5'], 'Orta dikme (3, 4)\'ten geçer ve eğimi −3/4\'tür: 3x + 4y = 25. y = 0 için x = 25/3\'tür.'),
  ('Köşeleri A(0, 0), B(4, 0) ve C(1, 3) olan üçgenin diklik merkezi hangi noktadır?', '(1, 1)', ['(2, 1)', '(1, 2)', '(5/3, 1)'], 'C\'den yükseklik x = 1\'dir. A\'dan BC\'ye yükseklik y = x\'tir (BC eğimi −1). Kesişim (1, 1)\'dir.'),
  ('A(0, 0), B(4, 0) ve C(1, 3) köşeli üçgenin diklik merkezi, ağırlık merkezi ve çevrel çember merkezi aynı doğru üzerindedir. Bu doğrunun denklemi hangisidir?', 'y = 1', ['y = x', 'x = 2', 'y = 2x − 3'], 'Diklik merkezi (1, 1), ağırlık merkezi (5/3, 1), çevrel çember merkezi (2, 1)\'dir. Üçü de y = 1 doğrusu üzerindedir.'),
  ('Köşeleri (0, 0), (4, 0) ve (0, 3) olan üçgenin kenarlarının üzerinde 8 kafes noktası vardır. Pick teoremine göre üçgenin iç bölgesinde kaç kafes noktası bulunur?', '3', ['2', '6', '5'], 'Alan 6\'dır. A = İ + S/2 − 1 formülünde 6 = İ + 4 − 1 olduğundan İ = 3\'tür.'),
  ('Birbirinden Öklid uzaklığı 10 birim olan iki noktanın Manhattan uzaklığı en fazla kaç birim olabilir?', '10√2', ['20', '10', '15'], 'a² + b² = 100 iken |a| + |b| en çok √2·10\'dur; bu, |a| = |b| olduğunda gerçekleşir.'),
  ('x eksenine merkezli olan ve (0, 2) ile (4, 0) noktalarından geçen çemberin yarıçapı kaçtır?', '5/2', ['2', '3/2', '√13'], 'Merkez (a, 0) olsun. (a − 4)² = a² + 4 denkleminden a = 3/2 bulunur. r = |4 − 3/2| = 5/2\'dir.'),
  ('mx² + my² − 4x + 8y − 1 = 0 denkleminin bir çember belirtmesi için m hangi değerleri alabilir?', 'm > −20 ve m ≠ 0', ['m > 0', 'm < 20 ve m ≠ 0', 'm ≥ −20'], 'm ≠ 0 için denklem m\'ye bölünür. r² = 20/m² + 1/m = (20 + m)/m² > 0 olmalıdır; bu m > −20 ve m ≠ 0 demektir.'),
  ('Her iki koordinat ekseni teğet olan ve (2, 1) noktasından geçen iki çemberin merkezleri arasındaki uzaklık kaç birimdir?', '4√2', ['6', '4', '2√10'], 'Merkez (r, r) ve (2 − r)² + (1 − r)² = r² ise r² − 6r + 5 = 0, r = 1 ya da 5\'tir. Merkezler (1, 1) ve (5, 5) olup uzaklık 4√2\'dir.'),
  ('Birinci bölgede yer alan, her iki eksene teğet ve yarıçapı 4 olan çemberin orijine en yakın noktasının orijine uzaklığı kaç birimdir?', '4(√2 − 1)', ['4√2', '4(√2 + 1)', '4'], 'Merkez (4, 4), orijine uzaklığı 4√2\'dir. En yakın nokta merkez doğrultusunda r kadar yakında olur: 4√2 − 4.'),
  ('A(1, 2), B(5, 2) ve C(3, 6) noktalarından geçen çemberin yarıçapı kaçtır?', '5/2', ['2√2', '3', '√10'], 'AB\'nin orta dikmesi x = 3\'tür. Merkez (3, k): 4 + (k − 2)² = (6 − k)² ise k = 7/2 ve r² = 25/4\'tür.'),
  ('x² + y² = 25 çemberi için P(1, 2) noktasının çember üzerindeki noktalara en kısa ve en uzun uzaklıklarının çarpımı kaçtır?', '20', ['25', '5√5', '30'], '|OP| = √5\'tir. En kısa uzaklık 5 − √5, en uzun 5 + √5 olur. Çarpım 25 − 5 = 20\'dir.'),
  ('(x − 3)² + (y − 4)² = 4 çemberi üzerinde orijine en yakın noktanın koordinatları hangisidir?', '(9/5, 12/5)', ['(6/5, 8/5)', '(21/5, 28/5)', '(3/2, 2)'], 'Merkez (3, 4), orijine uzaklığı 5\'tir. En yakın nokta merkez doğrultusunda 3 birim uzaklıktadır: (3/5)(3, 4) = (9/5, 12/5).'),
  ('4x − 3y + k = 0 doğrusu (x − 2)² + (y − 1)² = 9 çemberine teğet ise k\'nın alabileceği değerlerin toplamı kaçtır?', '−10', ['10', '−20', '5'], 'Uzaklık |8 − 3 + k|/5 = 3 ise |k + 5| = 15 olur. k = 10 ya da −20; toplam −10\'dur.'),
  ('x − y + 1 = 0 doğrusunun x² + y² = 25 çemberinden ayırdığı kirişin orta noktası hangisidir?', '(−1/2, 1/2)', ['(1/2, −1/2)', '(−1, 1)', '(0, 1)'], 'Kirişin orta noktası, merkezden doğruya inen dikmenin ayağıdır: −c/(a² + b²)·(a, b) = −1/2·(1, −1) = (−1/2, 1/2).'),
  ('x² + y² = 25 çemberinin M(1, 2) noktasını orta nokta kabul eden kirişinin bulunduğu doğrunun denklemi hangisidir?', 'x + 2y = 5', ['2x + y = 4', 'x + 2y = 25', '2x − y = 0'], 'OM\'nin eğimi 2\'dir; kiriş ona dik olduğundan eğimi −1/2\'dir. y − 2 = −(x − 1)/2\'den x + 2y = 5 bulunur.'),
  ('A(0, 0), B(6, 0) noktaları ve |PA| : |PB| = 1 : 2 koşulunu sağlayan P noktalarının geometrik yeri olan çemberin yarıçapı kaçtır?', '4', ['2√3', '3', '6'], '4|PA|² = |PB|² olduğundan 4(x² + y²) = (x − 6)² + y² yazılır. Düzenlenirse (x + 2)² + y² = 16 bulunur; r = 4.'),
  ('A(−3, 0) ve B(3, 0) noktalarına uzaklıklarının kareleri toplamı 50 olan P noktası hareket ederken çizdiği çemberin yarıçapı nedir?', '4', ['5', '√50', '25'], '(x + 3)² + y² + (x − 3)² + y² = 50 ise 2x² + 2y² + 18 = 50 ve x² + y² = 16 olur. r = 4\'tür.'),
  ('A(0, 0), B(4, 0) ve |PA|² − |PB|² = 16 koşulunu sağlayan P(x, y) noktalarının geometrik yeri hangisidir?', 'x = 4 doğrusu', ['x = 2 doğrusu', 'y = 4 doğrusu', 'Merkezi orijinde bir çember'], 'x² + y² − (x − 4)² − y² = 8x − 16 = 16 olur ve x = 4 bulunur. Bu, y eksenine paralel bir doğrudur.'),
  ('A(4, 0) noktası sabittir ve B noktası x² + y² = 4 çemberi üzerinde hareket ediyor. AB doğru parçasının orta noktasının geometrik yeri nedir?', 'Merkezi (2, 0) ve yarıçapı 1 olan çember', ['Merkezi (2, 0) ve yarıçapı 2 olan çember', 'Merkezi (4, 0) ve yarıçapı 1 olan çember', 'Merkezi (0, 0) ve yarıçapı 3 olan bir çember'], 'Orta nokta ((4 + a)/2, b/2) olur. a² + b² = 4 ise (x − 2)² + y² = 1 elde edilir.'),
  ('x² + y² ≤ 25 eşitsizliğini sağlayan tam sayı koordinatlı kaç nokta vardır?', '81', ['78', '100', '69'], 'Sayma yapıldığında orijin, eksenler ve tüm kafes noktaları dahil 81 nokta bulunur.'),
  ('x² + y² ≤ 1 koşulunu sağlayan her (x, y) için 3x + 4y ifadesinin alabileceği en büyük değer kaçtır?', '5', ['7,5', '1', '3'], '3x + 4y = 5 doğrusu x² + y² = 1 çemberine teğettir (uzaklık 5/5 = 1). Daire bu doğrunun bir tarafında kaldığından en büyük değer 5\'tir.'),
  ('P(5, 0) noktasından x² + y² = 9 çemberine çizilen iki teğetin değme noktalarını birleştiren doğrunun denklemi nedir?', '5x = 9', ['5x = 25', 'x = 3', 'x = 5/9'], 'Kutup doğrusu x₀x + y₀y = r² biçimindedir. P(5, 0) için 5x = 9 olur.'),
  ('P(5, 0) noktasından x² + y² = 9 çemberine çizilen teğetlerin değme noktalarını birleştiren kirişin uzunluğu kaçtır?', '24/5', ['6', '24/25', '4'], 'Teğet uzunluğu √(25 − 9) = 4\'tür. Kirişin uzunluğu 2·(r·t/d) = 2·(3·4/5) = 24/5\'tir.'),
  ('P(4, 0) noktasından x² + y² = 4 çemberine çizilen teğetlerin değme noktaları A ve B ise OAPB dörtgeninin alanı kaç birimkaredir?', '4√3', ['2√3', '8√3/3', '8√3'], 'Teğet uzunluğu √(16 − 4) = 2√3\'tür. Dörtgen iki dik üçgenden oluşur; alan 2·(1/2)·2·2√3 = 4√3\'tür.'),
  ('A(a − 1, 2a − 7) noktasının eksenlere uzaklıkları eşittir. a\'nın alabileceği değerlerin toplamı kaçtır?', '26/3', ['6', '8/3', '−26/3'], '|a − 1| = |2a − 7| olmalıdır. a − 1 = 2a − 7 ise a = 6; a − 1 = 7 − 2a ise a = 8/3. Toplam 26/3\'tür.'),
  ('A(0, 0), B(4, 2), C(2, 6) ve D(−2, 4) noktalarını sırayla birleştiren dörtgen hangisidir?', 'Kare', ['Dikdörtgen', 'Eşkenar dörtgen', 'Paralelkenar'], 'Kenarların hepsi √20, köşegenlerin ikisi de √40\'tır. Kenarları eşit ve köşegenleri eşit olan dörtgen karedir.'),
  ('A(1, 2) ve B(4, 5) noktaları veriliyor. C noktası AB doğrusu üzerinde, B\'nin ötesinde ve |CA| : |CB| = 3 : 1 olacak biçimdedir. C noktası hangisidir?', '(11/2, 13/2)', ['(5/2, 7/2)', '(7, 8)', '(−11/2, −13/2)'], 'C, B\'nin ötesindedir: C = (3B − A)/2 = ((12 − 1)/2, (15 − 2)/2) = (11/2, 13/2).'),
  ('A(0, 0), B(4, 1), C(6, 5) ve D(2, 4) köşeli paralelkenarda |AC|² + |BD|² değeri kaçtır?', '74', ['61', '148', '37'], '|AC|² = 61, |BD|² = 13\'tür; toplam 74\'tür. Paralelkenarın köşegen kareleri toplamı, kenar kareleri toplamının iki katıdır: 2(17 + 20) = 74.'),
  ('x² + y² = 25 çemberi üzerindeki (x, y) noktaları için x + y toplamının en büyük değeri kaçtır?', '5√2', ['10', '5√2/2', '7'], 'x + y = k doğrusu çembere teğet olduğunda k en büyüktür: |k|/√2 = 5 ise k = 5√2\'dir.'),
  ('x² + y² − 6x + 8 = 0 çemberine orijinden çizilen teğetlerin eğimleri hangileridir?', '±√2/4', ['±2√2/4', '±√2', '±1/4'], 'Çemberin merkezi (3, 0), yarıçapı 1\'dir. y = mx için 3|m|/√(m² + 1) = 1 olur; 8m² = 1 ve m = ±√2/4.'),
  ('O(0, 0), B(4, 0) ve C(0, 3) köşeli üçgenin iç teğet çemberi ile çevrel çemberinin merkezleri arasındaki uzaklık kaç birimdir?', '√5/2', ['1', '√2', '3√5/2'], 'İç merkez (1, 1), çevrel merkez hipotenüsün orta noktası (2, 3/2)\'dir. Uzaklık √(1 + 1/4) = √5/2\'dir.'),
  ('O(0, 0), B(4, 0) ve C(0, 3) köşeli üçgende O köşesinden çizilen iç açıortay BC kenarını hangi noktada keser?', '(12/7, 12/7)', ['(2, 3/2)', '(3/2, 2)', '(−12/7, 12/7)'], 'Açıortay teoremine göre |BD| : |DC| = 4 : 3\'tür. D = (3B + 4C)/7 = (12/7, 12/7) bulunur ve bu nokta y = x üzerindedir.'),
  ('3x − 4y = 0 ve 4x + 3y = 0 doğrularının açıortay doğrularından biri aşağıdakilerden hangisidir?', '7x − y = 0', ['3x − 7y = 0', '7x + y = 0', 'x − 7y = 0'], '(3x − 4y)/5 = ±(4x + 3y)/5 olur. + işaretiyle −x − 7y = 0, yani x + 7y = 0; − işaretiyle 7x − y = 0 elde edilir.'),
  ('x + 2y − 4 = 0 ve 2x − y − 3 = 0 doğrularının kesiştiği noktayı orijine birleştiren doğrunun denklemi nedir?', 'x − 2y = 0', ['2x − y = 0', 'x − 2y + 4 = 0', '2x + y = 0'], '(x + 2y − 4) + m(2x − y − 3) = 0 demetinde orijin için −4 − 3m = 0 ve m = −4/3 olur. Düzenlenirse x − 2y = 0 bulunur.'),
  ('A(1, 1) merkezli noktasal simetri uygulanırsa 3x − 2y + 5 = 0 doğrusu hangi doğruya dönüşür?', '3x − 2y − 7 = 0', ['3x − 2y + 7 = 0', '3x + 2y − 7 = 0', '−3x + 2y − 7 = 0'], '(x, y) yerine (2 − x, 2 − y) yazılır: 3(2 − x) − 2(2 − y) + 5 = 0. Düzenlenirse 3x − 2y − 7 = 0 bulunur.'),
  ('Bir öğrenci (x − 1)² + (y − 2)² = 5 çemberine (2, 4) noktasında teğet olan doğrunun denklemini 2x + 4y = 5 olarak yazıyor. Doğru denklem hangisidir?', 'x + 2y = 10', ['x + 2y = 5', '2x + y = 8', '2x + 4y = 20'], 'Merkez (1, 2) olduğundan teğet formülü (x₀ − 1)(x − 1) + (y₀ − 2)(y − 2) = 5 olur: (x − 1) + 2(y − 2) = 5, yani x + 2y = 10.'),
  ('A(1, 2) ve B(5, 4) noktaları veriliyor. y ekseni üzerindeki P noktası için |PA| + |PB| toplamı en az kaçtır?', '2√10', ['4√2', '√40 + 2', '2√13'], 'A\'nın y eksenine göre simetriği A\'(−1, 2) alınır. En küçük toplam |A\'B| = √(36 + 4) = 2√10\'dur.'),
  ('(4, 3) noktasından geçen ve birinci bölgede koordinat eksenleriyle üçgen oluşturan doğrular arasında en küçük alanlı üçgenin alanı kaç birimkaredir?', '24', ['24√2', '48', '50'], 'En küçük alan, doğru (4, 3) noktasını eksen kesimlerinin orta noktası yapacak biçimde olduğunda elde edilir: kesimler 8 ve 6, alan 24\'tür.'),
  ('(2, 1) noktasından geçen bir doğru birinci bölgede koordinat eksenleriyle alanı 4 birimkare olan bir üçgen oluşturuyor. Bu doğrunun denklemi hangisidir?', 'x + 2y = 4', ['2x + y = 5', '2x + 3y − 7 = 0', 'x + 4y = 6'], 'Kesimler a ve b için 2/a + 1/b = 1 ve ab = 8\'dir. Bu b = 2, a = 4 verir; doğru x/4 + y/2 = 1, yani x + 2y = 4\'tür.'),
  ('Merkezleri arasındaki uzaklık 5 olan ve yarıçapları 3 ile 1 olan iki çemberin iç ortak teğetinin değme noktaları arasındaki parçanın uzunluğu kaç birimdir?', '3', ['√21', '4', '2√6'], 'İç ortak teğet parçasının uzunluğu √(d² − (r₁ + r₂)²) = √(25 − 16) = 3\'tür.'),
  ('y = 2x + 1 doğrusu orijin etrafında 90° saat yönünün tersine döndürülürse hangi doğru elde edilir?', 'x + 2y + 1 = 0', ['2x + y + 1 = 0', '−x + 2y + 1 = 0', 'x + 2y − 1 = 0'], 'Dönmede (x, y) → (−y, x) olur. Yeni nokta (X, Y) için x = Y, y = −X yazılır: −X = 2Y + 1, yani X + 2Y + 1 = 0.'),
  ('Bir arsanın sınırı x ≥ 0, y ≥ 0, x + 2y ≤ 8 ve 3x + y ≤ 9 koşullarıyla verilmiştir. Arsanın yüzölçümü nedir?', '17/2', ['9', '12', '−17/2'], 'Köşeler (0, 0), (3, 0), (2, 3) ve (0, 4)\'tür. Ayakkabı bağı toplamı 0 + 9 + 8 + 0 = 17 ve alan 17/2\'dir.'),
  ('Manhattan (taksi) uzaklığında A(0, 0) ve B(4, 0) noktalarına eşit uzaklıkta olan noktaların kümesi nedir?', 'x = 2 doğrusu', ['y = 2 doğrusu', 'Merkezi (2, 0) olan bir kare', 'x + y = 4 doğrusu'], '|x| + |y| = |x − 4| + |y| eşitliğinden |x| = |x − 4| ve x = 2 bulunur. Küme yine x = 2 doğrusudur.'),
  ('x² + y² + Dx + Ey + F = 0 çemberinin x eksenine teğet olması için hangi koşul gerekir ve yeterlidir?', 'D² = 4F', ['E² = 4F', 'D² + E² = 4F', 'D = E'], 'y = 0 için x² + Dx + F = 0 olur. Tek çözüm (teğetlik) için diskriminant sıfırdır: D² − 4F = 0.'),
  ('k ≠ 0 olmak üzere x² + y² + kx − 6y + 9 = 0 çemberi hangi eksene her k için teğettir?', 'y eksenine', ['x eksenine', 'Her iki eksene', 'Hiçbir eksene'], 'x = 0 için y² − 6y + 9 = (y − 3)² = 0 olur ve tek çözüm vardır; çember k ne olursa olsun y eksenine teğettir.'),
  ('P(0, 10) noktasından x² + y² = 25 çemberine çizilen teğetlerin değme noktalarının ordinatı kaçtır?', '5/2', ['5', '15/2', '25/10 + 5'], 'Değme noktalarını birleştiren kutup doğrusu y₀y = r², yani 10y = 25\'tir. Her iki değme noktasının ordinatı 5/2\'dir.'),
  ('(0, 0), (4, 2) ve (2, 6) köşeli üçgenin sınırında 6 kafes noktası vardır. Pick teoremine göre iç bölgesinde kaç kafes noktası bulunur?', '8', ['10', '4', '6'], 'Alan |4·6 − 2·2|/2 = 10\'dur. 10 = İ + 6/2 − 1 olduğundan İ = 8\'dir.'),
  ('A(0, 0), B(4, 0) ve C(2, 4) köşeli üçgenin alanını iki eşit parçaya bölen ve x eksenine paralel olan doğrunun denklemi hangisidir?', 'y = 4 − 2√2', ['y = (4 − 2√2)/2', 'y = 4 − √2', 'y = 2√2'], 'Üstte kalan üçgen asıl üçgene benzer ve alanı yarısıdır; benzerlik oranı 1/√2\'dir. Yükseklik 4/√2 = 2√2 olduğundan doğru y = 4 − 2√2\'dir.'),
  ('A(−3, 0), B(3, 0) ve C(0, 4) köşeli üçgenin çevrel çemberinin yarıçapı kaç birimdir?', '25/8', ['5/2', '25/16', '7/8'], 'Merkez y ekseni üzerindedir: (0, k). 9 + k² = (4 − k)² ise k = 7/8 ve R = 4 − 7/8 = 25/8\'dir.'),
  ('Genel denklemi x² + y² − 8x − 6y + 16 = 0 olan çember ile iki koordinat ekseninin kesişim kümesi kaç elemanlıdır?', '1', ['0', '2', '3'], '(x − 4)² + (y − 3)² = 9\'dur. x eksenine (4, 0)\'da teğettir; y eksenine uzaklık 4 > 3 olduğundan y eksenini kesmez. Toplam 1 ortak nokta vardır.'),
  ('Orijinden (x − 2)² + (y − 2)² = 4 çemberine çizilen teğetler hangileridir?', 'x = 0 ve y = 0 doğruları', ['y = x ve y = −x doğruları, çünkü merkez y = x üzerindedir', 'x = 2 ve y = 2 doğruları, çünkü merkezin koordinatları 2\'dir', 'Yalnız y = x doğrusu'], 'Çemberin merkezi (2, 2), yarıçapı 2\'dir; merkezin her iki eksene uzaklığı yarıçapa eşittir. Çember iki eksene de teğettir ve eksenler orijinden geçer.'),
  ('Bir P noktasının x = −2 doğrusuna uzaklığı, A(2, 0) noktasına uzaklığına eşittir. P\'nin geometrik yerinin denklemi nedir?', 'y² = 8x', ['y² = 4x', 'x² = 8y', 'x² + y² = 4'], '|x + 2| = √((x − 2)² + y²) karesi alınırsa x² + 4x + 4 = x² − 4x + 4 + y² ve y² = 8x bulunur.'),
  ('ABCD karesinin komşu köşeleri A(0, 0) ve B(3, 1) olup köşeler saat yönünün tersine sıralanmıştır. C köşesi hangisidir?', '(2, 4)', ['(4, −2)', '(3, 4)', '(−1, 3)'], 'AB = (3, 1) vektörü 90° saat yönünün tersine döndürülürse (−1, 3) olur. C = B + (−1, 3) = (2, 4)\'tür.'),
  ('x² + y² = r² (r pozitif tam sayı) çemberi üzerinde tam sayı koordinatlı en az 12 nokta bulunması için r en az kaç olmalıdır?', '5', ['3', '4', '10'], 'r = 1, 2, 3, 4 için çember üzerinde yalnız eksenlerdeki 4 kafes noktası vardır. r = 5\'te (±3, ±4), (±4, ±3) ve eksenlerdeki noktalarla 12 nokta olur.'),
  ('Koordinat eksenlerine teğet olan ve x + y = 6 doğrusuna da teğet olan, birinci bölgedeki iki çemberden küçüğünün yarıçapı kaçtır?', '6 − 3√2', ['(6 − 3√2)/2', '6 + 3√2', '3√2'], 'Merkez (r, r) için |2r − 6|/√2 = r olur. 2r − 6 = ±r√2 çözülürse küçük kök r = 6/(2 + √2) = 6 − 3√2\'dir.'),
  ('P(3, −2) noktasının y = 2x doğrusuna göre simetriği hangi noktadır?', '(−17/5, 6/5)', ['(−2, 3)', '(17/5, −6/5)', '(−17/5, −6/5)'], 'Doğru 2x − y = 0\'dır; P için değer 8\'dir. Simetrik nokta P − 2·8/5·(2, −1) = (−17/5, 6/5)\'tir.'),
  ('Yarıçapı 3 olan, orijin merkezli kapalı dairenin içinde ve üzerinde kaç kafes noktası bulunur?', '29', ['25', '32', '37'], 'x = 0 için 7, x = ±1 için 5\'er, x = ±2 için 5\'er ve x = ±3 için 1\'er nokta vardır. Toplam 7 + 10 + 10 + 2 = 29\'dur.'),
];
